CREATE TABLE IF NOT EXISTS gis_canonical_identity_crosswalk (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reconciliation_run_id uuid NOT NULL REFERENCES gis_state_constrained_resolution_runs(id), source_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id), target_feature_id uuid REFERENCES gis_spatial_features(id), canonical_state_code text NOT NULL, source_lga_code text NOT NULL, target_lga_code text, confidence text NOT NULL, review_required boolean NOT NULL, match_score numeric(6,5) NOT NULL DEFAULT 0, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, locked_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_feature_id));
CREATE INDEX IF NOT EXISTS idx_gis_canonical_crosswalk_state ON gis_canonical_identity_crosswalk(canonical_state_code,review_required);
CREATE INDEX IF NOT EXISTS idx_gis_canonical_crosswalk_conf ON gis_canonical_identity_crosswalk(confidence,review_required);